import { useRef, useLayoutEffect } from 'react';

/**
 * Renders a fixed-width HTML document (e.g. a frozen A4 invoice) and
 * scales it DOWN to fit narrow screens, so the whole document is visible
 * at its real proportions — no horizontal scroll, no squished columns.
 * Never scales up (full size when there's room, e.g. desktop). Resets to
 * full size when printing.
 *
 * The inner HTML is trusted (generated by our own renderer).
 */
export default function ScaledDocument({ html }) {
  const wrapRef = useRef(null);
  const innerRef = useRef(null);

  useLayoutEffect(() => {
    const wrap = wrapRef.current;
    const inner = innerRef.current;
    if (!wrap || !inner) return;

    const measure = () => {
      // Measure the document's natural size, unscaled.
      inner.style.transform = 'none';
      inner.style.width = 'max-content';
      const naturalW = inner.scrollWidth;
      const naturalH = inner.scrollHeight;
      if (!naturalW) return;
      const avail = wrap.clientWidth;
      const s = avail < naturalW ? avail / naturalW : 1;
      inner.style.transformOrigin = 'top left';
      inner.style.transform = `scale(${s})`;
      // Collapse the wrapper to the scaled height so there's no dead space
      // below the document (transform doesn't affect layout box).
      wrap.style.height = s < 1 ? `${Math.ceil(naturalH * s)}px` : '';
    };

    measure();
    // Re-measure on container resize and once more after layout settles
    // (web fonts / late reflow can change the document's height).
    const ro = new ResizeObserver(measure);
    ro.observe(wrap);
    const t = setTimeout(measure, 150);
    return () => { ro.disconnect(); clearTimeout(t); };
  }, [html]);

  return (
    <div
      ref={wrapRef}
      className="overflow-hidden print:!h-auto print:!overflow-visible"
    >
      <div
        ref={innerRef}
        className="print:!transform-none print:!w-auto"
        dangerouslySetInnerHTML={{ __html: html }}
      />
    </div>
  );
}
